/* Automatic illustrative bond percolation and scalar load transfer.
 * The committed data is generated by content_tools/generate_fibernet_flow.py.
 * No specimen data or FEM claims are attached to this decorative scene.
 */
(()=>{
  'use strict';
  const reduced=matchMedia('(prefers-reduced-motion: reduce)');
  const coarse=matchMedia('(pointer: coarse)');
  const clamp=(v,a=0,b=1)=>Math.max(a,Math.min(b,v));
  const mix=(a,b,f)=>a+(b-a)*f;
  document.querySelectorAll('.fn-flow-canvas').forEach(async canvas=>{
    const ctx=canvas.getContext('2d',{alpha:true});
    if(!ctx)return;
    let data;
    try{
      const response=await fetch(canvas.dataset.flowSrc);
      if(!response.ok)throw Error('Network scene unavailable');
      data=await response.json();
    }catch(error){console.warn(error.message);return;}
    const {nodes,edges,frames:states,threshold}=data;
    const projected=nodes.map(()=>({x:0,y:0,z:0}));
    const order=edges.map((edge,id)=>({a:edge[0],b:edge[1],id}));
    const nodeOrder=nodes.map((_,id)=>id);
    let width=0,height=0,dpr=1,clock=4,raf=0,last=0,frames=0,inView=false;
    let dark=true,drawn=0,occupancy=.8,spanning=true;
    const modest=(navigator.hardwareConcurrency||8)<=4;
    function palette(){dark=document.documentElement.dataset.theme!=='light';draw();request();}
    function visible(){return inView&&!document.hidden&&width>0&&height>0;}
    function measureVisibility(){
      const r=canvas.getBoundingClientRect();
      inView=r.bottom>0&&r.right>0&&r.top<innerHeight&&r.left<innerWidth;
    }
    function draw(){
      if(!width||!height)return;
      // Increase and decrease bond occupancy slowly; normalize loads once at export.
      const statePosition=reduced.matches?24:(.5+.5*Math.sin(clock*.2-.3))*(states.length-1);
      const i=Math.floor(statePosition),j=Math.min(i+1,states.length-1),f=statePosition-i;
      const current=states[i],next=states[j];occupancy=mix(current.occupancy,next.occupancy,f);spanning=current.spans||next.spans;
      const yaw=-.42+Math.sin(clock*.085)*.33,pitch=-.27+Math.cos(clock*.09)*.06,roll=-.055;
      const cy=Math.cos(yaw),sy=Math.sin(yaw),cx=Math.cos(pitch),sx=Math.sin(pitch),cr=Math.cos(roll),sr=Math.sin(roll);
      const scale=Math.min(width*.295,height*.44);
      for(let k=0;k<nodes.length;k++){
        const p=nodes[k],x=p[0]*cy+p[2]*sy,z0=-p[0]*sy+p[2]*cy,y=p[1]*cx-z0*sx,z=p[1]*sx+z0*cx;
        const perspective=5.8/(5.8-z),out=projected[k];
        out.x=width*.5+(x*cr-y*sr)*scale*perspective;
        out.y=height*.5-(x*sr+y*cr)*scale*perspective;out.z=z;
      }
      ctx.clearRect(0,0,width,height);ctx.lineCap='round';
      order.sort((p,q)=>(projected[p.a].z+projected[p.b].z)-(projected[q.a].z+projected[q.b].z));
      const energies=new Float32Array(nodes.length);
      const pulse=(clock*.19)%1.5-.18;
      drawn=0;
      for(const e of order){
        const a=projected[e.a],b=projected[e.b],depth=clamp(.5+(a.z+b.z)*.25);
        const active=clamp((occupancy-threshold[e.id])/.04+.5);
        const load=mix(current.load[e.id],next.load[e.id],f);
        const energy=Math.pow(load,.55);
        const arrival=(mix(current.front[e.a],next.front[e.a],f)+mix(current.front[e.b],next.front[e.b],f))*.5;
        const wave=Math.exp(-Math.pow((arrival-pulse)/.12,2));
        ctx.beginPath();ctx.moveTo(a.x,a.y);ctx.lineTo(b.x,b.y);
        ctx.strokeStyle=dark?'#66869c':'#55738a';
        ctx.globalAlpha=(dark?.07:.11)+depth*.08+active*(dark?.12:.09);
        ctx.lineWidth=.65+active*.22;ctx.stroke();
        if(energy>.035){
          energies[e.a]=Math.max(energies[e.a],energy);energies[e.b]=Math.max(energies[e.b],energy);
          ctx.strokeStyle=dark?(energy>.52?'#f5bd76':'#75c8c5'):(energy>.52?'#b65b29':'#167e88');
          ctx.globalAlpha=clamp(.12+energy*.60+wave*energy*.3)*( .65+depth*.35);
          ctx.lineWidth=.75+energy*1.65+wave*.4;ctx.stroke();drawn++;
          // A short moving glint follows only the stronger load-bearing edges.
          if(energy>.32&&wave>.35){
            const fa=mix(current.front[e.a],next.front[e.a],f),fb=mix(current.front[e.b],next.front[e.b],f);
            const t=clamp((pulse-fa)/(fb-fa||.001));
            if(t>0&&t<1){
              ctx.beginPath();ctx.arc(mix(a.x,b.x,t),mix(a.y,b.y,t),1.15+energy*.4,0,Math.PI*2);
              ctx.fillStyle=dark?'#ffdcab':'#9e4b1d';ctx.globalAlpha=wave*.8;ctx.fill();
            }
          }
        }
      }
      nodeOrder.sort((a,b)=>projected[a].z-projected[b].z);
      for(const id of nodeOrder){
        const p=projected[id],depth=clamp(.5+p.z*.5),energy=energies[id];
        ctx.beginPath();ctx.arc(p.x,p.y,.85+depth*.55+energy*.5,0,Math.PI*2);
        ctx.fillStyle=energy>.45?(dark?'#efc48f':'#ad6435'):(dark?'#8cbec9':'#467a90');
        ctx.globalAlpha=.25+depth*.35+energy*.25;ctx.fill();
      }
      ctx.globalAlpha=1;frames++;
    }
    function frame(t){
      raf=0;if(!visible()){last=0;return;}
      const interval=coarse.matches||modest?50:33.3;
      if(last&&t-last<interval){request();return;}
      if(last&&!reduced.matches)clock+=Math.min(.15,(t-last)/1000);
      last=t;draw();if(!reduced.matches)request();else last=0;
    }
    function request(){if(visible()&&!raf)raf=requestAnimationFrame(frame);}
    function stop(){if(raf)cancelAnimationFrame(raf);raf=0;last=0;}
    function resize(){
      const r=canvas.getBoundingClientRect();width=r.width;height=r.height;
      if(!width||!height){stop();return;}
      dpr=Math.min(devicePixelRatio||1,Math.sqrt(2000000/(width*height)));
      canvas.width=Math.round(width*dpr);canvas.height=Math.round(height*dpr);
      ctx.setTransform(canvas.width/width,0,0,canvas.height/height,0,0);
      measureVisibility();draw();request();
    }
    function resume(){measureVisibility();last=0;request();}
    if('ResizeObserver' in window)new ResizeObserver(resize).observe(canvas);
    if('IntersectionObserver' in window)new IntersectionObserver(entries=>{
      inView=entries[0].isIntersecting;if(inView)resume();else stop();
    },{threshold:0}).observe(canvas);
    window.addEventListener('resize',resize,{passive:true});
    window.addEventListener('scroll',()=>{const before=inView;measureVisibility();if(inView&&!before)resume();else if(!inView)stop();},{passive:true});
    document.addEventListener('visibilitychange',()=>document.hidden?stop():resume());
    window.addEventListener('pagehide',stop,{passive:true});window.addEventListener('pageshow',resume,{passive:true});
    reduced.addEventListener('change',()=>{stop();draw();resume();});coarse.addEventListener('change',resize);
    new MutationObserver(palette).observe(document.documentElement,{attributes:true,attributeFilter:['data-theme']});
    canvas.fibernetFlow={snapshot:()=>({nodes:nodes.length,edges:edges.length,frames,clock,occupancy,spanning,loadEdges:drawn,
      inView,running:!!raf,reduced:reduced.matches,width,height,pixelRatio:dpr,backingWidth:canvas.width,backingHeight:canvas.height}),
      finite:()=>projected.every(p=>Number.isFinite(p.x)&&Number.isFinite(p.y)&&Number.isFinite(p.z))};
    canvas.dataset.ready='true';resize();palette();
  });
})();
